dict(set=3, konu="Teminat ve Faiz", kalip="YANLIŞ", z="Z",
 madde="GY 495/1-c, 495/1-ç, 495/1-e, 495/2, 495/3",
 cek="GY'ye göre esham yüzde on beş noksanla değerlenir, garanti mektubunda ihlal bir yıl yasak getirir; teminat mektupları süresiz olmalıdır.",
 kok=["Gümrük Yönetmeliği'ne göre gümrük işlemleri sırasında kabul olunabilecek teminatlar ve bunların değerlendirilmesine ilişkin aşağıdakilerden hangisi yanlıştır?"],
 d="Teminat mektuplarının alacak miktarını karşılayacak değerde ve süreli olması gerekir.",
 c=["Millî Esham ve Tahvilât, teminatın kabul edilmesine en yakın borsa cetvelleri üzerinden yüzde on beş noksanıyla değerlendirilir.",
     "Nominal bedele faiz dâhil edilerek ihraç edilmiş devlet iç borçlanma senetlerinde anaparaya tekabül eden satış değerleri esas alınır.",
     "Garanti mektubu ile işlem yapılmasında yükümlülükler tam ve zamanında yerine getirilmezse yükümlüye bir yıl boyunca bu haktan yararlanma izni verilmez.",
     "Sermayesinin tamamı devlete ait kamu iktisadi teşebbüslerinin verecekleri garanti mektupları teminat olarak kabul olunur."],
 g="Gümrük Yönetmeliği'ne göre teminat mektuplarının Yönetmelikteki kayıt ve şartlara uygun, alacak miktarını karşılayacak değerde ve süresiz olması gerekir; bu nedenle 'süreli' ifadesi yanlıştır. Diğer ifadeler doğrudur: Millî Esham ve Tahvilât en yakın borsa cetvelleri üzerinden %15 noksanıyla değerlendirilir; nominal bedele faiz dâhil edilerek ihraç edilmiş devlet iç borçlanma senetlerinde anaparaya tekabül eden satış değerleri esas alınır; garanti mektubu ile işlem yapılması durumunda yükümlülüklerin tam ve zamanında yerine getirilmemesi hâlinde yükümlüye bir yıl boyunca bu haktan yararlanma izni verilmez; genel yönetim kapsamındaki kamu idareleri, belediyeler, sermayesinin tamamı devlete ait kamu iktisadi teşebbüsleri ve Türkiye'deki yabancı misyon şeflerinin garanti mektupları teminat olarak kabul olunur (özel firmaların garanti mektupları bu kapsamda değildir). Bu nedenle doğru cevap 'Teminat mektuplarının alacak miktarını karşılayacak değerde ve süreli olması gerekir.' seçeneğidir. (MD GY 495)",
 kanit="46-teminat ve faiz.txt | (3) Teminat mektuplarının 497 nci maddedeki kayıt ve şartlara uygun, alacak miktarını karşılayacak değerde ve süresiz olması gerekir.",
 cikmis="2025/29, 2022/92"),

dict(set=3, konu="Geri Verme-Kaldırma", kalip="OLAY", z="O",
 madde="GK 213/1, 213/2, 213/3, 213/4; GY 501/1",
 cek="Kusurlu eşya ilk kullanım dışında kullanılmamışsa ihraç yerine serbest bölgeye konulabilir; başvuru vergilerin tebliğinden itibaren bir yıl içinde yapılır.",
 kok=["4458 sayılı Gümrük Kanunu ve Gümrük Yönetmeliği'ne göre, beyannamenin tescili tarihi itibarıyla kusurlu olduğu gerekçesiyle ithalatçı tarafından kabul edilmeyen eşyaya ilişkin aşağıdaki geri verme taleplerinden hangisi kabul edilir? (Hiçbir talepte mücbir sebep bulunmamaktadır.)"],
 d="Kusurun tespiti için gerekli ilk kullanım dışında kullanılmayan makinenin serbest bölgeye konulması istenmiş, başvuru tebliğden on ay sonra yapılmıştır.",
 c=["Kusurlu olduğu teyit edildikten sonra eşya yurt içinde satılmış, başvuru vergilerin tebliğinden üç ay sonra yapılmıştır.",
     "Satış fiyatı belirlenirken eşyanın kusurlu mahiyeti dikkate alınmış, eşya ihraç edilmiş ve başvuru vergilerin tebliğinden iki ay sonra yapılmıştır.",
     "İlk kullanım dışında kullanılmayan eşya ihraç edilmiş, başvuru vergilerin tebliğinden on dört ay sonra yapılmıştır.",
     "Gümrük beyanından önce denenmek üzere teslim edilen eşyanın kusurunun deneme sırasında anlaşılamadığı kanıtlanamamıştır."],
 g="Gümrük Kanunu'na göre beyannamenin tescili tarihi itibarıyla kusurlu olduğundan ithalatçı tarafından kabul edilmeyen eşyanın ithalat vergileri, kusurun tespiti için gerekli ilk kullanım dışında eşyanın kullanılmamış olması ve Türkiye Gümrük Bölgesi dışına ihraç edilmesi koşuluyla geri verilir; gümrük idareleri ilgilinin talebi üzerine ihraç yerine imhaya, yeniden ihraç amacıyla transit veya antrepo rejimine tabi tutmaya ya da serbest bölgeye konulmaya izin verir. Başvurunun vergilerin tebliğinden itibaren bir yıl içinde yapılması gerekir; on aylık başvuru bu süre içindedir. Kusur teyit edildikten sonra eşyanın satılması ve fiyat belirlenirken kusurun dikkate alınması hâllerinde vergiler geri verilmez; on dört ay sonra yapılan başvuru süre dışındadır; denenmek üzere teslim edilen eşyada kusurun deneme sırasında anlaşılamadığı kanıtlanmadıkça vergiler geri verilmez. Bu nedenle doğru cevap serbest bölgeye konulması istenen ve tebliğden on ay sonra başvurulan makineye ilişkin seçenektir. (MD GK 213/1-4; GY 501/1)",
 kanit="47-geri verme kaldırma.txt | Gümrük idareleri, ilgilinin talebi üzerine, eşyanın ihracı yerine; imhasına, yeniden ihraç amacıyla transit veya gümrük antrepo rejimine tabi tutulmasına veya serbest bölgeye konulmasına izin verirler.",
 cikmis="2025/26"),

