dict(set=4, konu="Tahakkuk-Tebliğ-Ödeme", kalip="SÜRE", z="O",
 madde="GK 198/1, 198/2",
 cek="Noksan vergiler tebliğden itibaren on beş gün içinde ödenir; itiraz ödeme süresini keser, süre itiraz kararının tebliğinden itibaren yeniden başlar.",
 kok=["(N) firmasına, yapılan kontrol sonucunda noksan alındığı belirlenen gümrük vergileri 02.06.2025 tarihinde tebliğ edilmiştir. Firma 09.06.2025 tarihinde gümrük idaresine itiraz etmiş; itirazın reddine ilişkin karar 07.07.2025 tarihinde firmaya tebliğ edilmiştir. Firma ödeme süresinin uzatılmasını talep etmemiş ve yargı yoluna başvurmamıştır.",
      "4458 sayılı Gümrük Kanunu'na göre (N) firması noksan vergileri en geç hangi tarihe kadar ödemek zorundadır?"],
 d="22.07.2025",
 c=["17.06.2025", "15.07.2025", "06.08.2025", "24.06.2025"],
 g="Gümrük Kanunu'na göre kontrol ve denetlemeler sonucunda hiç alınmadığı veya noksan alındığı belirlenen gümrük vergilerinin, yükümlüye tebliğ edildiği tarihten itibaren on beş gün içinde ödenmesi zorunludur. Tebliğ edilen vergilere karşı gümrük idaresi nezdinde itiraz edilmesi ödeme süresini keser ve ödeme süresi idarenin kararının tebliğ edildiği tarihten itibaren yeniden başlar; yani kalan süre değil, on beş günlük sürenin tamamı yeniden işler. İtirazın reddi 07.07.2025 tarihinde tebliğ edildiğinden son ödeme günü 22.07.2025'tir. İlk tebliğden hesaplama (17.06.2025), itirazdan önce kalan süreyle devam etme (15.07.2025), otuz günlük süre uygulama (06.08.2025) veya süreyi itiraz tarihinden başlatma (24.06.2025) hatalıdır. Bu nedenle doğru cevap 22.07.2025'tir. (MD GK 198/1, 198/2)",
 kanit="45-tebliğ.txt | Tebliğ edilen gümrük vergilerine karşı 242 nci madde çerçevesinde gümrük idareleri nezdinde itiraz edilmesi ödeme süresini keser. Ödeme süresi idarenin ya da yargı mercii kararının tebliğ edildiği tarihten itibaren yeniden başlar.",
 cikmis="2024/81, 2025/27, 2022/88"),

